questionvariables.text:
/* Step 1: Define the function */
num:rand(3)+1;
lower_lm:rand(6);
b:2+rand(6);
upper_lm:lower_lm+2+rand(5);
point_disc:upper_lm;
den:sqrt(b*point_disc - b*x);
fx : num/den;
/* Step 2: Check the integral */
integral_exp: int(fx, x, lower_lm, upper_lm);




/*Worked Solution code*/
limit_check : limit(fx, x, point_disc);
/* Step 3: Change of variables */
uu : b*point_disc - b*x;
del_x : diff(uu, x);
del_dx : diff(uu, x)*dx;
/* Step 4: Set up new limits */
u1 : ev(uu, x =lower_lm); /* x =lower_lm u= ? */
u2 : ev(uu, x = t); /*x=b, u=? upper limit */
/* Step 5: Integrate */
fu: num/sqrt(u)*1/(del_x);
new_indef : int(fu, u);
/* Compute the definite integral from a to b */
upper: at(new_indef, u = u2);
lower: at(new_indef, u = u1);
indef_val: upper - lower;

/* Step 6: Evaluate the limit */
result : limit(indef_val, t, point_disc); /* limit as t approaches 4 */

/*Model answers*/
ta_1: integral_exp;
ta_2:if ta_1=inf then "Divergent" elseif ta_1=minf then "Divergent" else"Convergent";
ta_3:if ta_2="Divergent" then "Convergent" else "Divergent";
ta_4:random_permutation([[ta_2, true],[ta_3, false],["Divergent and convergent", false]]);

